63	  if (IsA2OrA3Soc(soc_name)) {
64	    HIXL_LOGI("[NotifyResolver] Resolve notify address by HCCP. device_id=%d soc=%s", device_id, soc_name);
65	    return HccpProxy::RaGetNotifyAddrLen(device_id, notify, notify_addr, notify_len);
66	  }
67	  HIXL_LOGI("[NotifyResolver] Resolve notify address by runtime. device_id=%d soc=%s", device_id, soc_name);
68	  return ResolveNotifyDeviceAddressByRuntime(notify, notify_addr, notify_len);
69	}
