10	
11	#include "host_register_proxy.h"
12	#include "common/hixl_checker.h"
13	#include "common/hixl_log.h"
14	#include "common/hixl_utils.h"
15	
16	namespace hixl {
17	
18	namespace {
19	std::map<int32_t, std::shared_ptr<HostRegisterProxy>> g_proxy_instances;
20	std::mutex g_proxy_mutex;
21	}  // namespace
22	
23	std::shared_ptr<HostRegisterProxy> HostRegisterProxy::GetOrCreateInstance(uint32_t dev_phy_id) {
24	  auto get_proxy = GetInstance(dev_phy_id);
25	  if (get_proxy != nullptr) {
26	    return get_proxy;
27	  }
28	  if (dev_phy_id > INT32_MAX) {
29	    HIXL_LOGE(PARAM_INVALID, "dev_phy_id=%u is invalid.", dev_phy_id);
30	    return nullptr;
31	  }
32	  auto dev_phy_id_int = static_cast<int32_t>(dev_phy_id);
33	  std::lock_guard<std::mutex> lock(g_proxy_mutex);
34	  auto &proxy = g_proxy_instances[dev_phy_id_int];
35	  if (proxy != nullptr) {
36	    return proxy;
37	  }
38	  proxy.reset(new (std::nothrow) HostRegisterProxy(dev_phy_id_int));
39	  return proxy;
40	}
41	
42	std::shared_ptr<HostRegisterProxy> HostRegisterProxy::GetInstance(uint32_t dev_phy_id) {
43	  if (dev_phy_id > INT32_MAX) {
44	    HIXL_LOGE(PARAM_INVALID, "dev_phy_id=%u is invalid.", dev_phy_id);
45	    return nullptr;
46	  }
47	
48	  auto dev_phy_id_int = static_cast<int32_t>(dev_phy_id);
49	  std::lock_guard<std::mutex> lock(g_proxy_mutex);
50	  auto it = g_proxy_instances.find(dev_phy_id_int);
51	  if (it != g_proxy_instances.end()) {
52	    return it->second;
53	  }
54	  return nullptr;
55	}
56	
57	HostRegisterProxy::HostRegisterProxy(int32_t dev_phy_id) : dev_phy_id_(dev_phy_id) {}
58	
59	HostRegisterProxy::~HostRegisterProxy() {
60	  std::lock_guard<std::mutex> lock(mutex_);
61	  for (auto &pair : registered_mems_) {
62	    void *host_addr = pair.first;
63	    HIXL_LOGI("host_addr has not been unregistered. host_addr=%p, ref_cnt=%d.", host_addr, pair.second.ref_cnt);
64	    const aclError ret = aclrtHostUnregister(host_addr);
65	    if (ret != ACL_ERROR_NONE) {
66	      HIXL_LOGE(ret, "Failed to unregister host memory in destructor. host_addr=%p", host_addr);
67	    }
68	  }
69	  registered_mems_.clear();
70	}
71	
72	Status HostRegisterProxy::RegisterByDev(uint32_t dev_phy_id, void *host_addr, uint64_t size, void *&device_addr) {
73	  auto proxy = GetOrCreateInstance(dev_phy_id);
74	  HIXL_CHECK_NOTNULL(proxy);
75	  return proxy->Register(host_addr, size, device_addr);
76	}
77	
78	Status HostRegisterProxy::UnregisterByDev(uint32_t dev_phy_id, void *host_addr) {
79	  auto proxy = GetOrCreateInstance(dev_phy_id);
80	  HIXL_CHECK_NOTNULL(proxy);
81	  return proxy->Unregister(host_addr);
82	}
83	
84	Status HostRegisterProxy::GetRegisteredDeviceAddrByDev(uint32_t dev_phy_id, void *host_addr, void *&device_addr) {
85	  auto proxy = GetInstance(dev_phy_id);
86	  HIXL_CHECK_NOTNULL(proxy);
87	  return proxy->GetRegisteredDeviceAddr(host_addr, device_addr);
88	}
89	
90	Status HostRegisterProxy::GetRegisteredDeviceAddr(void *host_addr, void *&device_addr) const {
91	  std::lock_guard<std::mutex> lock(mutex_);
92	  auto it = registered_mems_.find(host_addr);
93	  if (it != registered_mems_.end()) {
94	    device_addr = it->second.device_addr;
95	    return SUCCESS;
96	  }
97	  return FAILED;
98	}
99	
100	Status HostRegisterProxy::Register(void *host_addr, uint64_t size, void *&device_addr) {
101	  HIXL_CHECK_NOTNULL(host_addr);
102	
103	  std::lock_guard<std::mutex> lock(mutex_);
104	  auto it = registered_mems_.find(host_addr);
105	  if (it != registered_mems_.end()) {
106	    if (it->second.size != size) {
107	      HIXL_LOGE(PARAM_INVALID,
108	                "Host memory already registered with different size. host_addr=%p, cached_size=%lu, request_size=%lu",
109	                host_addr, it->second.size, size);
110	      return PARAM_INVALID;
111	    }
112	    it->second.ref_cnt++;
113	    device_addr = it->second.device_addr;
114	    HIXL_LOGI("Host memory already registered, host_addr=%p, device_addr=%p, size=%lu, ref_cnt=%d.", host_addr,
115	              device_addr, size, it->second.ref_cnt);
116	    return SUCCESS;
117	  }
118	  void *dev_ptr = nullptr;
